import assert from "node:assert/strict";
import { test } from "node:test";
import {
  formatShellCommand,
  quoteWindowsArgument,
  readNodeCmdShim,
} from "./shell-command.ts";
// These bytes were generated by cmd-shim 9.0.2 and @zkochan/cmd-shim
// 9.0.8 from a real #!/usr/bin/env node --trace-warnings script.
const npm =
  '@ECHO off\r\nGOTO start\r\n:find_dp0\r\nSET dp0=%~dp0\r\nEXIT /b\r\n:start\r\nSETLOCAL\r\nCALL :find_dp0\r\n\r\nIF EXIST "%dp0%\\node.exe" (\r\n  SET "_prog=%dp0%\\node.exe"\r\n) ELSE (\r\n  SET "_prog=node"\r\n)\r\n\r\nendLocal & goto #_undefined_# 2>NUL || title %COMSPEC% & set PATHEXT=%PATHEXT:;.JS;=;% & "%_prog%" --trace-warnings "%dp0%\\..\\source.js" %*\r\n';
const pnpm =
  '@SETLOCAL\r\n@IF EXIST "%~dp0\\node.exe" (\r\n  "%~dp0\\node.exe"  --trace-warnings "%~dp0\\..\\source.js" %*\r\n) ELSE (\r\n  @SET PATHEXT=%PATHEXT:;.JS;=;%\r\n  node  --trace-warnings "%~dp0\\..\\source.js" %*\r\n)\r\n';
const shell = {
  id: "powershell",
  label: "PowerShell",
  executable: "powershell.exe",
  args: [],
};
test("npm and pnpm Node shim files retain the script and fixed Node arguments", () => {
  for (const source of [npm, pnpm])
    assert.deepEqual(readNodeCmdShim(source), {
      script: "..\\source.js",
      args: ["--trace-warnings"],
    });
  assert.equal(readNodeCmdShim("@echo off\r\nnode other.js %*\r\n"), undefined);
  assert.equal(readNodeCmdShim(npm + "echo extra\r\n"), undefined);
  assert.equal(
    readNodeCmdShim(npm.replaceAll("source.js", "%NAME%.js")),
    undefined,
  );
  assert.equal(
    readNodeCmdShim(pnpm.replace("node  --trace-warnings", "node --other")),
    undefined,
  );
});
test("CRT quoting preserves quotes, empty arguments and runs of trailing backslashes", () => {
  assert.equal(quoteWindowsArgument(""), '""');
  assert.equal(quoteWindowsArgument('a" b'), '"a\\" b"');
  assert.equal(quoteWindowsArgument("C:\\a b\\"), '"C:\\a b\\\\"');
  assert.equal(quoteWindowsArgument("C:\\a b\\\\"), '\"C:\\a b\\\\\\\\"');
});
test("POSIX output and persisted commands keep the original CLI expression", () => {
  const posix = { ...shell, id: "bash" };
  assert.equal(
    formatShellCommand("codex", ["-c", "a'b\nc"], posix),
    "codex '-c' 'a'\\''b\nc'",
  );
  assert.equal(
    formatShellCommand("codex.cmd", ["--model", "mini"], shell, {
      stored: true,
      rawArguments: "--profile mine",
    }),
    "& 'codex.cmd' --profile mine '--model' 'mini'",
  );
});
